function UIEntrusts:RefeshSelf(status, levelId, selectCb, isOpenFromHome)
    self._status = checkNumber(status)
    self._selectCb = selectCb
    if not isNull(levelId) then
        self._curLevelId = checkString(levelId)
    end
    self._isOpenFromHome = isOpenFromHome
    self:RefeshLevelStatus()

    self._allEntrustQueues = teamComponent:GetAllEntrustArr()
    if not self._allEntrustQueues then
        return
    end
    if not self._isInitView then
        self.CommonHangUpTeams:InitListView(#self._allEntrustQueues, Bind(self, self.OnGetItemByIndex))
        self._isInitView = true
    else
        GameUtils.ReloadData(self.CommonHangUpTeams, #self._allEntrustQueues)
    end
    cs_coroutine.start(function()
        --cs_coroutine.yield_return(Yielders.GetWaitForSeconds(0.25))
        KTool.SetActive(self.CommonHangUpTeams, true)
        --if self._curSelectQueueId and self.isFirstOpen then
        --    self.isFirstOpen = false
        --    self.CommonHangUpTeams:MovePanelToItemIndex(checkNumber(self._curSelectQueueId) - 1)
        --end
        KTool.SetActive(self.controller.gameObject, true)
    end)
    self.Content:SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, self.CommonHangUpTeams.ViewPortWidth)

end

function UIEntrusts:MovePanel()
    if self._curSelectQueueId then
        if checkNumber(self._curSelectQueueId) <= 2 then
            self.Content.anchoredPosition = Vector2.New(self.Content.anchoredPosition.x, 0)
        else
            self.Content.anchoredPosition = Vector2.New(self.Content.anchoredPosition.x, 430)
        end
    end
end

