                if isUnlock then
                    if self._isOpenFromHome then--从主页进入
                        if isHaveTask and isEntrustingEnd then
                            self._curSelectQueueId = data.id
                            scr:RefreshSelect(true)
                            self:MovePanel()

                            if self._selectCb then
                                self._selectCb(self._curSelectQueueId)
                            end
                        elseif isHaveTask and (not self:HasEndEntrustQueue()) then
                            self._curSelectQueueId = data.id
                            scr:RefreshSelect(true)
