                            end
                        end
                    else--从关卡进入
                        if (not self._isLevelEntrusting) and (not isHaveTask) then
                            self._curSelectQueueId = data.id
                            scr:RefreshSelect(true)
                            self:MovePanel()

                            if self._selectCb then
                                self._selectCb(self._curSelectQueueId)
                            end
                        --elseif self._isLevelEntrusting and isHaveTask then
                            
                        end
                    end

                end

                --elseif (not self._curSelectQueueId) and (not self._isOpenFromHome) and (not self._isLevelEntrusting) and (not isHaveTask) and isUnlock then
                --    printInfo("===1.5")
                --
                --    self._curSelectQueueId = data.id
                --    scr:RefreshSelect(true)
                --    if self._selectCb then
                --        self._selectCb(self._curSelectQueueId)
                --    end
                --elseif(not self._curSelectQueueId) and isHaveTask and isUnlock and isEntrustingEnd then
                --
                --    printInfo("===2")
                --    self._curSelectQueueId = data.id
                --    scr:RefreshSelect(true)
                --    if self._selectCb then
                --        self._selectCb(self._curSelectQueueId)
                --    end
                --elseif (not self._curSelectQueueId) and isHaveTask and isUnlock then
                --    printInfo("===3")
                --    self._curSelectQueueId = data.id
                --    scr:RefreshSelect(true)
                --    if self._selectCb then
                --        self._selectCb(self._curSelectQueueId)
                --    end
                --elseif (not self._curSelectQueueId) and (not isHaveTask) and isUnlock and (not self:HasEndEntrustQueue()) then
