function UIEntrusts:OnSelectTeam(scr, data, isHaveTask)
    --如果当前关卡在委托中都没有点击效果
    if self._isLevelEntrusting then
        GameUtils.Toast(localize("当前关卡委任中，不可切换编队"))
        --如果是编队选择的时候 没任务才可以点击
    elseif self._status == STATUS.TEAMSELECT and (self._isOpenFromHome or ( not isHaveTask ))then
        local goLast = self.CommonHangUpTeams:GetShownItemByItemIndex(self:GetCurEntrustIndex())
        if goLast then
            --printInfo("11111111111==="..self:GetCurEntrustIndex())
            local lastScr = CfUtils.GetLuaScr(goLast, UIEntrustQueueNode)
            if lastScr then
                lastScr:RefreshSelect(false)
            end
        end
        scr:RefreshSelect(true)
        self._curSelectQueueId = data.id
        if self._selectCb then
            self._selectCb(data.id)
        end
    elseif not (self._isOpenFromHome and isHaveTask) then
        GameUtils.Toast(localize("该队列正在委托中"))
    end
end

--取消委托
function UIEntrusts:OnBtnGetCancel(entrustId)
    GameUtils.SecondConfirm(localize("是否确定取消任务？"), function()
        teamComponent:EntrustGetRewardReq(entrustId)
    end, nil, localize("取消委任不会返还扣除的体力(已完成_num_场)", {_num_ = teamComponent:GetAllEntrustTime(entrustId)}))
end

--刷新状态
function UIEntrusts:RefeshLevelStatus()
    local entrustData = teamComponent:GetEntrustQueueDataByQuestId(self._curLevelId)
    if entrustData then
        self._isLevelEntrusting = true
        self._curSelectQueueId = entrustData.id      --当前选择的队列id
    else
        if not isNull(self.rewardGetQueueId) then
            self._curSelectQueueId = self.rewardGetQueueId
        else
            self._curSelectQueueId = teamComponent:GetLastSelectEntrustQueue()
        end
        self._isLevelEntrusting = false
    end
end

--委托数据刷新界面
function UIEntrusts:OnEntrustDataRefesh(body)
    self:RefeshLevelStatus()
    self._allEntrustQueues = teamComponent:GetAllEntrustArr()
    GameUtils.ReloadData(self.CommonHangUpTeams, #self._allEntrustQueues)
end

--委托成功后回调刷新界面
function UIEntrusts:OnUIEntrustBattleSuccess(body)
    self:RefeshLevelStatus()
    self._allEntrustQueues = teamComponent:GetAllEntrustArr()
    GameUtils.ReloadData(self.CommonHangUpTeams, #self._allEntrustQueues)
end

---委托领取奖励刷新指定队列和右侧关卡选择
function UIEntrusts:OnEntrustRewardGet(id)
    if isNull(id) then
        return
    end
    self.rewardGetQueueId = id
    self:OnEntrustDataRefesh()
end

function UIEntrusts:GetCurEntrustIndex()
    if not self._allEntrustQueues then
        return 0
    end
    for k, v in pairs(self._allEntrustQueues) do
        if checkNumber(v.id) == checkNumber(self._curSelectQueueId) then
            return checkNumber(k) - 1
        end
    end
    return 0
end

---是否有已完成委托的队列
function UIEntrusts:HasEndEntrustQueue()
    if isNull(self._allEntrustQueues) then
        return false
    end
    local has = false
    for i = 1, #self._allEntrustQueues do
        local isHaveTask = teamComponent:IsEntrustQueuesBusy(self._allEntrustQueues[i].id)
        if isHaveTask and teamComponent:IsEntrustingEnd(self._allEntrustQueues[i].id) then
            has = true
            break
        end
    end
    return has
end

function UIEntrusts:OnDestroy()
    if not isNull(self) then
        Events.RemoveListener(Constants.EventNames.EntrustDataRefesh, self.EventEntrustDataRefesh)
        Events.RemoveListener(Constants.EventNames.UIEntrustBattleSuccess, self.EventUIEntrustBattleSuccess)
        Events.RemoveListener(Constants.EventNames.EntrustRewardGet, self.EventEntrustRewardGet)
    end
    teamComponent:RefeshEntrustRedPointNum()

    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIEntrusts
